mapper.update:
UPDATE bko_app_info SET
  delete_state = #{deleteState,jdbcType=BIGINT}
WHERE id = #{id,jdbcType=VARCHAR}

mapper.select:
SELECT app.*, institute.institute_name
FROM bko_app_info AS app
LEFT JOIN inc_institute AS institute ON institute.id = app.institute_id
WHERE app.delete_state = 0

  AND app.app_name LIKE CONCAT('%', #{appName,jdbcType=VARCHAR}, '%')


  AND app.appkey LIKE CONCAT('%', #{appkey,jdbcType=VARCHAR}, '%')


  AND ( app.appkey LIKE CONCAT('%', #{keyword,jdbcType=VARCHAR}, '%')
   OR app.app_name LIKE CONCAT('%', #{keyword,jdbcType=VARCHAR}, '%')
  )


  AND app.institute_id = #{instituteId,jdbcType=VARCHAR}


  AND app.module_id = #{moduleId,jdbcType=VARCHAR}


  AND app.template_type = #{templateType,jdbcType=CHAR}

    AND app.id NOT IN (
      SELECT inherit.parent_id
      FROM bko_app_inherit AS inherit
      WHERE inherit.app_id = #{inheritAppId,jdbcType=VARCHAR}
    )



  AND app.`status` = #{status,jdbcType=CHAR}
